// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { PieChart } from "@/registry/erbium/charts/pie-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import CenterExample from "./variants/center";



const meta = {
  component: PieChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Pass one row per slice. `index` names each slice and `value` sizes it. Slices take the chart colors in data order; pass `series` to set labels or colors by slice name.

```tsx
import { PieChart } from "@/registry/erbium/charts/pie-chart";

<PieChart ariaLabel="Visitors by browser" data={browsers} index="browser" value="visitors" />;
```

Keep a pie to five slices and group the rest into "Other". When slices are close in size, compare them in a [Bar Chart](/docs/charts/bar-chart) instead.",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof PieChart>;

export default { ...meta, title: "Charts/Pie Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{ donut: boolean; legend: boolean; tooltip: boolean }> = {
  argTypes: {
    donut: { control: "boolean" },
    legend: { control: "boolean" },
    tooltip: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { PieChart } from "@/registry/erbium/charts/pie-chart";
import { browsers } from "../examples/data";

export const defaultProps = {
  donut: true,
  legend: true,
  tooltip: true,
} satisfies { donut: boolean; legend: boolean; tooltip: boolean };

export default function PieChartPlaygroundExample(
  args: { donut: boolean; legend: boolean; tooltip: boolean } = defaultProps,
) {
  return (
    <div className="w-md max-w-full p-4">
      <PieChart
        ariaLabel="Visitors by browser"
        data={browsers}
        index="browser"
        value="visitors"
        initialWidth={400}
        {...args}
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Center: Story = {
  parameters: {
    docs: {
      description: { story: "`center` places HTML over the donut's hole, here the total. It does not take pointer events, so slices under it still respond to hover." },
      source: { code: "import { PieChart } from "@/registry/erbium/charts/pie-chart";
import { browsers } from "../examples/data";

const total = browsers.reduce((sum, row) => sum + row.visitors, 0);

export default function PieChartCenterExample() {
  return (
    <div className="w-md max-w-full p-4">
      <PieChart
        ariaLabel="Visitors by browser"
        data={browsers}
        index="browser"
        value="visitors"
        initialWidth={400}
        center={
          <>
            <span className="text-subtitle tabular-nums">{total.toLocaleString("en")}</span>
            <span className="text-metadata text-muted-foreground">Visitors</span>
          </>
        }
      />
    </div>
  );
}
" },
    },
  },
  render: CenterExample,
};

import { PieChart } from "@/registry/erbium/charts/pie-chart";
import { browsers } from "../examples/data";

const total = browsers.reduce((sum, row) => sum + row.visitors, 0);

export default function PieChartCenterExample() {
  return (
    <div className="w-md max-w-full p-4">
      <PieChart
        ariaLabel="Visitors by browser"
        data={browsers}
        index="browser"
        value="visitors"
        initialWidth={400}
        center={
          <>
            <span className="text-subtitle tabular-nums">{total.toLocaleString("en")}</span>
            <span className="text-metadata text-muted-foreground">Visitors</span>
          </>
        }
      />
    </div>
  );
}

